# frozen_string_literal: true
require "application_system_test_case"

# The department admin routes use the route types generated by react-router typegen (Route.ClientActionArgs) and read
# their data with the typed hooks, so this exercises their loaders and actions in a real browser. Runs in both the
# data-mode and framework-mode system test runs.
class DepartmentAdminTest < ApplicationSystemTestCase
  let(:root_site) { create(:root_site) }
  let(:convention) { create(:convention, :with_standard_content) }

  before do
    root_site
    Intercode.overridden_virtual_host_domain = convention.domain
    admin = create(:site_admin)
    create(:user_con_profile, convention:, user: admin)
    sign_in admin
  end

  after { Intercode.overridden_virtual_host_domain = nil }

  it "creates a department" do
    visit "/admin_departments"
    click_link "New department"
    fill_in "Name", with: "Games"
    click_button "Create"

    assert page.has_content?("Games")
    assert_equal "Games", convention.departments.reload.sole.name
  end

  it "edits a department" do
    department = Department.create!(convention:, name: "Games")

    visit "/admin_departments/#{department.id}/edit"
    assert page.has_content?("Editing Games")
    fill_in "Name", with: "Board games"
    click_button "Save"

    assert page.has_content?("Board games")
    assert_equal "Board games", department.reload.name
  end

  it "deletes a department" do
    department = Department.create!(convention:, name: "Games")

    visit "/admin_departments"
    click_button "Delete department"
    click_button "OK"

    assert page.has_no_content?("Games")
    assert_not Department.exists?(department.id)
  end
end
